#!/usr/bin/env python3
"""Extend 5th-grade fractions by 150 non-identical, deterministic interactive challenges.
Re-run is idempotent; original IDs never change. The JSON task bank is the source of truth.
"""
import json, csv, math
from pathlib import Path
from fractions import Fraction
ROOT=Path(__file__).resolve().parents[1]
path=ROOT/'data/tasks.json'
db=json.loads(path.read_text('utf8'))
old=[t for t in db['tasks'] if t['ogrenme_ciktisi'] in ('MAT.5.1.3','MAT.5.1.4')]
assert len(old)>=40
# Remove only entries generated by this version when rebuilding.
db['tasks']=[t for t in db['tasks'] if not t.get('v25_generated')]
all_ids={t['id'] for t in db['tasks']}
contexts=['Okul kütüphanesi','Sahil parkı','Sınıf sergisi','Bisiklet yolu','Paylaşım atölyesi','Bahçe tasarımı','Su deposu','Spor şenliği','Geri dönüşüm noktası','Okuma kulübü']
A=['stripPaint','hundredGrid','representationMatch','numberLine','equivalenceBridge','mixedImproper','pizzaShare','percentDial']
B=['numberLineDuel','compareSigns','sortCards','closestAnchor','errorDetect','fractionRelay','budgetChoice']
labels={'stripPaint':'Kesir şeridi inşası','hundredGrid':'Yüzlük pano boyama','representationMatch':'Gösterim eşleştirme','numberLine':'Sayı doğrusu haritacısı','equivalenceBridge':'Denklik köprüsü','mixedImproper':'Bileşik kesir dönüştürücü','pizzaShare':'Paylaşım masası','percentDial':'Yüzde çarkı','numberLineDuel':'Çift nokta düellosu','compareSigns':'Çapraz çarpım dedektifi','sortCards':'Gösterim sıralama yarışı','closestAnchor':'Referans noktası avı','errorDetect':'Yanlış çıkarım avcısı','fractionRelay':'Aralık köprüsü','budgetChoice':'Kaynak paylaştırma stratejisi'}
reps=[Fraction(1,2),Fraction(1,4),Fraction(3,4),Fraction(1,5),Fraction(2,5),Fraction(3,5),Fraction(4,5),Fraction(1,10),Fraction(3,10),Fraction(7,10)]
proper=[Fraction(1,3),Fraction(2,3),Fraction(1,4),Fraction(3,4),Fraction(2,5),Fraction(3,5),Fraction(4,5),Fraction(3,8),Fraction(5,8),Fraction(7,8)]
precise=[Fraction(1,4),Fraction(2,5),Fraction(1,2),Fraction(3,5),Fraction(3,4),Fraction(4,5),Fraction(1,5),Fraction(9,10),Fraction(3,10),Fraction(7,10)]
percent=lambda f:int(f*100)
fmt=lambda f:f'{f.numerator}/{f.denominator}'
num=lambda key,label,answer:dict(key=key,label=label,kind='number',answer=answer)
choice=lambda key,label,answer,options:dict(key=key,label=label,kind='choice',answer=str(answer),options=[str(x) for x in options])
rng=lambda key,label,answer,maxv=100,step=1:dict(key=key,label=label,kind='range',answer=answer,min=0,max=maxv,step=step)
rows=[]
for mode in A+B:
 for j in range(10):
  n=20+j+1 if mode in A else 20+j+1
  code='MAT.5.1.3' if mode in A else 'MAT.5.1.4'
  # unique sequential task numbers: old 20, 8*10 -> G21..G100; 7*10 -> G21..G90
  idx=(A.index(mode) if mode in A else B.index(mode))*10+j+21
  task_id=f'{code}-G{idx:02d}'
  assert task_id not in all_ids
  all_ids.add(task_id)
  f=reps[j];p=proper[j]; q=precise[j]
  fields=[];data={};instruction=''; tip='Bir bütünü eş parçalara ayır ve kullandığın gösterimleri birbirine bağla.'
  if mode=='stripPaint':
   den=[4,5,6,8,10,12,5,6,8,10][j]; count=[1,2,3,5,7,9,3,4,5,8][j]
   f=Fraction(count,den)
   data={'den':den,'num':count,'capacity':den,'equiv':fmt(Fraction(count*2,den*2))}
   fields=[dict(key='paint',label='Şeritte boyadığın eş parça sayısı',kind='paint',answer=count,capacity=den), choice('equiv','Aynı büyüklüğü gösteren kesri seç',f'{count*2}/{den*2}',[f'{count*2}/{den*2}',f'{count+1}/{den}',f'{count}/{den*2}'])]
   instruction=f'{den} eş parçalı şeritte {count}/{den} kadarını işaretle; sonra denk kesri seç.'
  elif mode=='hundredGrid':
   count=[10,20,25,30,35,40,45,50,65,75][j]
   data={'num':count,'den':100,'capacity':100}
   fields=[dict(key='paint',label='100 karede seçtiğin parça sayısı',kind='paint',answer=count,capacity=100),num('decimal','Ondalık gösterimi yaz',count/100)]
   instruction=f'Yüzlük panoda %{count} kadar alanı renklendir ve ondalık gösterimini yaz.'
  elif mode=='representationMatch':
   data={'num':f.numerator,'den':f.denominator,'percent':percent(f)}
   fields=[choice('percent','Doğru yüzde kartını seç',f'%{percent(f)}',[f'%{percent(f)}',f'%{min(100,percent(f)+10)}',f'%{max(0,percent(f)-10)}']),num('decimal','Ondalık gösterimini yaz',float(f))]
   instruction=f'{fmt(f)} kesrinin yüzdelik ve ondalık gösterimlerini eşleştir; kartla sayıyı aynı modeli gösterecek biçimde seç.'
  elif mode=='numberLine':
   numerator=[3,5,6,7,8,9,11,13,14,17][j];den=10
   x=Fraction(numerator,den)
   data={'num':numerator,'den':den,'max':200}
   fields=[rng('marker','0–2 sayı doğrusunda konum (%)',numerator*10,200,10),num('whole','İşaretlediğin noktanın tam kısmı',numerator//den)]
   instruction=f'{numerator}/{den} sayısını 0 ile 2 arasındaki sayı doğrusuna yerleştir ve tam kısmı belirle.'
  elif mode=='equivalenceBridge':
   base=[Fraction(1,2),Fraction(2,3),Fraction(3,4),Fraction(2,5),Fraction(3,5),Fraction(5,6),Fraction(3,8),Fraction(4,7),Fraction(2,9),Fraction(7,10)][j]
   factor=[2,3,4,2,3,2,4,3,2,4][j]
   data={'num':base.numerator,'den':base.denominator,'factor':factor}
   fields=[choice('factor','Her iki terimi kaçla çarpmalısın?',factor,[factor,1,factor+1]),num('newNumerator','Yeni şeridin boyalı parça sayısı',base.numerator*factor)]
   instruction=f'{fmt(base)} kesrinin {base.denominator*factor} parçalı yeni şeritteki denk modelini oluştur.'
  elif mode=='mixedImproper':
   den=[3,4,5,6,8,4,5,6,8,10][j];whole=[1,2,1,2,1,3,2,1,2,2][j];rem=[1,1,2,3,5,1,4,5,3,7][j];top=whole*den+rem
   data={'num':top,'den':den,'capacity':den}
   fields=[num('whole','Kaç bütün vardır?',whole),num('remainder','Son bütünün boyalı parça sayısı',rem)]
   instruction=f'{top}/{den} bileşik kesrini bütünler ve kalan parçalarla modelle; tam sayılı gösterimini oluştur.'
  elif mode=='pizzaShare':
   den=[2,3,4,5,6,8,3,4,5,8][j];whole=[1,1,2,2,1,1,3,2,3,1][j];rem=[1,2,1,3,5,3,1,3,4,7][j];top=whole*den+rem
   data={'num':top,'den':den,'whole':whole,'remainder':rem}
   fields=[rng('whole','Tamamlanmış bütün sayısı',whole,4,1),choice('remainder','Yeni bütünün gereken dilim sayısı',rem,[rem,(rem+1)%den, max(0,rem-1)])]
   instruction=f'Bir masa {top}/{den} tepsi yiyecek paylaşacak. Kaç tam tepsi ve kaç ek dilim gerekir?'
  elif mode=='percentDial':
   pct=[5,10,15,20,25,30,40,50,60,75][j];f=Fraction(pct,100)
   data={'percent':pct,'num':f.numerator,'den':f.denominator}
   fields=[rng('dial','Yüzde çarkını kaçta sabitlersin?',pct,100,5),choice('fraction','Çarka denk kesri seç',fmt(f),[fmt(f),fmt(Fraction(min(100,pct+10),100)),fmt(Fraction(max(0,pct-5),100))])]
   instruction=f'{pct}/100 oranlı alanı çark üzerinde belirle, kesir gösterimiyle eşleştir.'
  elif mode=='numberLineDuel':
   a=precise[j];b=precise[(j+3)%10]
   if a==b:b=precise[(j+4)%10]
   data={'a':fmt(a),'b':fmt(b),'av':float(a),'bv':float(b)}
   fields=[rng('markerA','A işaretinin yüzde konumu',percent(a)),rng('markerB','B işaretinin yüzde konumu',percent(b)),choice('sign','A ile B arasındaki karşılaştırma', '>' if a>b else '<' if a<b else '=', ['<','=','>'])]
   instruction=f'A={fmt(a)}, B={fmt(b)} noktalarını sayı doğrusuna yerleştirip büyüklüklerini karşılaştır.'
  elif mode=='compareSigns':
   a=proper[j];b=proper[(j+4)%10]
   data={'a':fmt(a),'b':fmt(b),'av':float(a),'bv':float(b)}
   sign='>' if a>b else '<' if a<b else '='
   fields=[choice('sign','Doğru matematiksel işaret',sign,['<','=','>']),num('cross','Soldaki çapraz çarpım: A payı × B paydası',a.numerator*b.denominator)]
   instruction=f'{fmt(a)} ile {fmt(b)} kesirlerini çapraz çarpım kanıtıyla karşılaştır.'
  elif mode=='sortCards':
   a=precise[j];b=precise[(j+3)%10];c=precise[(j+6)%10]
   vals=sorted(set([a,b,c])); k=0
   while len(vals)<3:
    vals.append(precise[(j+7+k)%10]);k+=1;vals=sorted(set(vals))
   cards=[{'label':fmt(vals[2]),'num':vals[2].numerator,'den':vals[2].denominator},{'label':str(percent(vals[0]))+'%','num':vals[0].numerator,'den':vals[0].denominator},{'label':str(float(vals[1])).replace('.',','),'num':vals[1].numerator,'den':vals[1].denominator}]
   data={'cards':cards}
   fields=[{'key':'sequence','kind':'sequence','label':'Küçükten büyüğe sıraladığın üç kart','answer':[1,2,0]}]
   instruction='Kartlar '+', '.join(card['label'] for card in cards)+' biçiminde yazılı. Farklı kesir, ondalık ve yüzde gösterimlerini küçükten büyüğe sırala.'
  elif mode=='closestAnchor':
   anchor=[0,0.5,1][j%3];vals=[Fraction(1,10),Fraction(2,5),Fraction(7,10)] if anchor==0 else ([Fraction(2,5),Fraction(9,10),Fraction(1,5)] if anchor==0.5 else [Fraction(3,4),Fraction(7,10),Fraction(9,10)])
   vals=vals[j%3:]+vals[:j%3]
   dists=[abs(float(v)-anchor) for v in vals];winner=dists.index(min(dists))
   data={'anchor':anchor,'cards':[{'label':fmt(x),'value':float(x)} for x in vals]}
   fields=[choice('winner','Referans noktasına en yakın kart',str(winner),[str(x) for x in range(3)]),num('distance','Uzaklık yüzde kaç?',round(min(dists)*100))]
   instruction=f'{str(anchor).replace(".",",")} referansına en yakın kesri seçip aradaki uzaklığı yüzde olarak bul.'
  elif mode=='errorDetect':
   a=proper[j];b=proper[(j+2)%10];truth='>' if a>b else '<' if a<b else '=';wrong='<' if truth=='>' else '>' if truth=='<' else '<'
   data={'a':fmt(a),'b':fmt(b),'av':float(a),'bv':float(b),'claim':wrong}
   fields=[choice('verdict','Verilen karşılaştırma doğru mu?','Yanlış',['Doğru','Yanlış']),choice('correct','Hangi işaret olmalı?',truth,['<','=','>'])]
   instruction=f'Robot “{fmt(a)} {wrong} {fmt(b)}” dedi. Sayı doğrusu modelinden yararlanarak hatayı belirle ve düzelt.'
  elif mode=='fractionRelay':
   mid=[Fraction(1,4),Fraction(2,5),Fraction(1,2),Fraction(3,5),Fraction(3,4),Fraction(2,5),Fraction(1,2),Fraction(3,5),Fraction(7,10),Fraction(4,5)][j]
   low=mid-Fraction(1,10);high=mid+Fraction(1,10)
   distract1=low;distract2=high
   data={'low':fmt(low),'high':fmt(high),'candidate':fmt(mid)}
   fields=[choice('between','Sınırlar arasında kalan kart',fmt(mid),[fmt(mid),fmt(distract1),fmt(distract2)]),choice('proof','Seçtiğin kesir her iki eşitsizliği sağlar mı?','Evet',['Hayır','Evet'])]
   instruction=f'Sayı doğrusu köprüsünde {fmt(low)} ile {fmt(high)} arasına, uçlara eşit olmayan bir kesir yerleştir.'
  elif mode=='budgetChoice':
   vals=[Fraction((j%5+1)*5,100),Fraction(40+(j%4)*5,100),Fraction(75+(j%3)*5,100)]
   vals=vals[j%3:]+vals[:j%3];high=max(vals);low=min(vals);w=vals.index(high)
   data={'cards':[{'label':('%'+str(percent(v))) if k==0 else (fmt(v) if k==1 else str(float(v)).replace('.',',')),'value':float(v)} for k,v in enumerate(vals)]}
   fields=[choice('winner','En yüksek paya sahip plan',str(w),['0','1','2']),num('diff','En yüksek ile en düşük arasındaki fark (%)',percent(high-low))]
   instruction='Üç kaynak planı '+', '.join(card['label'] for card in data['cards'])+' ile gösteriliyor. En yüksek payı seç ve en büyük ile en küçük payın yüzde farkını hesapla.'
  else: raise ValueError(mode)
  # Context is diverse but mechanics and parameter structures are independently meaningful.
  lvl=1+(j//2)
  task={'plan_sirasi':14 if code.endswith('1.3') else 15,'tema_sirasi':4,'tema':'Sayılar ve Nicelikler','tema_ici_sira':1 if code.endswith('1.3') else 2,'temanin_yaklasik_haftalari':'18–25','id':task_id,'ogrenme_ciktisi':code,'sinif':'5','gorev_no':str(idx),'seviye':str(lvl),'asama':['Keşfet','Modelle','Sına','Gerekçelendir','Uygula'][lvl-1],'rol':['Haritacı','Tasarımcı','Dedektif','Mühendis','Stratejist'][lvl-1],'mekan':contexts[j],'mekanik':labels[mode],'baslik':f'{labels[mode]} · {contexts[j]}','gorev':contexts[j]+': '+instruction,'kontrol_turu':'etkilesimli','beklenen_yanit_veya_rubrik':'Model doğrulama: '+', '.join(str(f['label'])+': '+str(f['answer']) for f in fields),'ipucu':tip if code=='MAT.5.1.3' else 'Kesirleri ortak gösterime veya sayı doğrusuna getir; kararını bir bağıntıyla kontrol et.','oyuncu_eylemi':'Görsel model üzerinde seçim yap ve doğrula','sure_dakika':'4' if lvl<4 else '6','ogrenci_urun':'Etkileşimli kesir modeli ve matematiksel karar','fraction5PlusLab':{'mode':mode,'seed':j,'visual':data,'fields':fields,'requireReason':lvl==5,'sourceOutcome':code,'surec_bilesenleri_oneri':{'MAT.5.1.3':{'stripPaint':['b','c'],'hundredGrid':['a','c'],'representationMatch':['a','ç'],'numberLine':['b','c'],'equivalenceBridge':['ç','d'],'mixedImproper':['a','c'],'pizzaShare':['c','d'],'percentDial':['ç','e']},'MAT.5.1.4':{'numberLineDuel':['a','c'],'compareSigns':['b','ç'],'sortCards':['a','c'],'closestAnchor':['a','c'],'errorDetect':['b','d'],'fractionRelay':['c','ç'],'budgetChoice':['ç','d']}}[code][mode]},'v25_generated':True}
  rows.append(task)
# Validate counts, indices and task-level uniqueness.
assert len(rows)==150
assert len({x['id'] for x in rows})==150
assert len([x for x in rows if x['ogrenme_ciktisi']=='MAT.5.1.3'])==80
assert len([x for x in rows if x['ogrenme_ciktisi']=='MAT.5.1.4'])==70
for row in rows:
 for f in row['fraction5PlusLab']['fields']:
  if f['kind']=='choice': assert str(f['answer']) in f['options'],(row['id'],f)
  if f['kind']=='paint':assert 0<=f['answer']<=f['capacity']
  if f['kind']=='range':assert f['min']<=f['answer']<=f['max'] and (f['answer']-f['min'])%f['step']==0,(row['id'],f)
# All older task order and IDs are unchanged. Only new tasks appended.
db['tasks']+=rows
for o in db['outcomes']:
 if o['kod']=='MAT.5.1.3':o.update({'etiket':'Gerçek yaşam durumlarına karşılık gelen kesirleri farklı biçimlerde temsil edebilme','resmi_metin':'Gerçek yaşam durumlarına karşılık gelen kesirleri farklı biçimlerde temsil edebilme','resmi_metin_mi':True,'kaynak_url':'https://tymm.meb.gov.tr/ortaokul-matematik-dersi/unite/449','alan_becerisi_tema':'MAB3. Matematiksel Temsil','egilimler_tema':['E1.1. Merak','E3.4. Gerçeği Arama'],'tema_degerleri':['D1. Adalet','D5. Duyarlılık','D14. Saygı','D16. Sorumluluk','D17. Tasarruf','D19. Vatanseverlik']})
 if o['kod']=='MAT.5.1.4':o.update({'etiket':'Farklı gösterimlerle ifade edilen kesirlerin karşılaştırılmasına yönelik çıkarım yapabilme','resmi_metin':'Farklı gösterimlerle ifade edilen kesirlerin karşılaştırılmasına yönelik çıkarım yapabilme','resmi_metin_mi':True,'kaynak_url':'https://tymm.meb.gov.tr/ortaokul-matematik-dersi/unite/449','kavramsal_beceri_tema':'KB2.10. Çıkarım Yapma','egilimler_tema':['E1.1. Merak','E3.4. Gerçeği Arama'],'tema_degerleri':['D1. Adalet','D5. Duyarlılık','D14. Saygı','D16. Sorumluluk','D17. Tasarruf','D19. Vatanseverlik']})
path.write_text(json.dumps(db,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
out=ROOT/'data/KESIRLER_150_YENI_GOREV.csv'
with out.open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f,delimiter=';');w.writerow(['ID','Öğrenme çıktısı','Tema','Oyun türü','Seviye','Görev','Bileşen','Doğrulama ölçütleri','MEB kaynak']);
 for t in rows:
  c=t['fraction5PlusLab'];w.writerow([t['id'],t['ogrenme_ciktisi'],t['tema'],t['mekanik'],t['seviye'],t['gorev'], 'Temsil' if t['ogrenme_ciktisi']=='MAT.5.1.3' else 'Çıkarım',json.dumps(c['fields'],ensure_ascii=False), 'https://tymm.meb.gov.tr/ortaokul-matematik-dersi/unite/449'])
(ROOT/'data/5_SINIF_KESIRLER_RESMI_ESLESME.json').write_text(json.dumps({'program':'Türkiye Yüzyılı Maarif Modeli, Ortaokul Matematik, 5. sınıf','tema':'Sayılar ve Nicelikler (2)','ders_saati':33,'url':'https://tymm.meb.gov.tr/ortaokul-matematik-dersi/unite/449','outcomes':{'MAT.5.1.3':{'resmi_metin':'Gerçek yaşam durumlarına karşılık gelen kesirleri farklı biçimlerde temsil edebilme','surec':['a','b','c','ç','d','e']},'MAT.5.1.4':{'resmi_metin':'Farklı gösterimlerle ifade edilen kesirlerin karşılaştırılmasına yönelik çıkarım yapabilme','surec':['a','b','c','ç','d']}},'tema_becerileri':['MAB3. Matematiksel Temsil','KB2.10. Çıkarım Yapma'],'tema_egilimleri':['E1.1. Merak','E3.4. Gerçeği Arama'],'tema_degerleri':['D1. Adalet','D5. Duyarlılık','D14. Saygı','D16. Sorumluluk','D17. Tasarruf','D19. Vatanseverlik'],'uyari':'Programın tema düzeyindeki eşlemeleridir. Bu görevlerin MEB tarafından onaylandığı anlamına gelmez.'},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print('NEW',len(rows),'TOTAL',len(db['tasks']),'G5',sum(t['sinif']=='5' for t in db['tasks']))
